import random

def parse(stdin):
    t = list(map(int, stdin.split()))
    assert len(t) >= 1 and t[0] == len(t) - 1
    return t[1:]

def render(case):
    return str(len(case)) + chr(10) + " ".join(map(str, case))

def valid(case):
    return isinstance(case, list) and 1 <= len(case) <= 8 and all(isinstance(x, int) and not isinstance(x, bool) and -9 <= x <= 9 for x in case)

def solve(stdin):
    a = parse(stdin)
    return str(max(sum(a[i:j]) for i in range(len(a)) for j in range(i + 1, len(a) + 1)))

def generate(seed, index, mode):
    if mode == "exhaustive":
        if index < 3:
            return [index - 1]
        if index < 12:
            k = index - 3
            return [k // 3 - 1, k % 3 - 1]
        return None
    if mode == "random":
        rnd = random.Random(seed + index)
        n = rnd.randint(1, 8)
        return [rnd.randint(-9, 9) for _ in range(n)]
    b = [[-9], [9], [0], [-9] * 8, [9] * 8, [0] * 8, [-9, 9] * 4, [9, -9] * 4]
    return b[index % len(b)]

def shrink(case):
    res = []
    if len(case) > 1:
        for i in range(len(case)):
            res.append(case[:i] + case[i + 1:])
    for i in range(len(case)):
        if case[i] != 0:
            c1, c2 = list(case), list(case)
            c1[i] = 0
            c2[i] = int(case[i] / 2)
            res.extend([c1, c2])
    out, seen = [], set()
    for c in res:
        t = tuple(c)
        if valid(c) and t != tuple(case) and t not in seen:
            seen.add(t)
            out.append(c)
            if len(out) == 16:
                break
    return out

