def valid_input(stdin):
    try:
        tokens = stdin.split()
        if not tokens:
            return False
        n = int(tokens[0])
        if not (1 <= n <= 8):
            return False
        if len(tokens) != 1 + n:
            return False
        for t in tokens[1:]:
            val = int(t)
            if not (-9 <= val <= 9):
                return False
        return True
    except Exception:
        return False

def solve(stdin):
    tokens = stdin.split()
    n = int(tokens[0])
    a = [int(x) for x in tokens[1:1 + n]]
    ans = max(sum(a[i:j]) for i in range(n) for j in range(i + 1, n + 1))
    return str(ans)
